<script setup lang="ts">import type {Scenario} from '../types';const props=defineProps<{scenario:Scenario}>();const spr=()=>{const s=props.scenario;if(s.opponents!==1||!s.stack.trim()||!s.villainStack.trim()||Number(s.pot)<=0)return null;const v=Math.min(Number(s.stack),Number(s.villainStack));return Number.isFinite(v)&&v>=0?(v/Number(s.pot)).toFixed(2):null};const emit=defineEmits<{update:[key:keyof Scenario,value:string]}>();</script><template><details class="panel"><summary>位置与抽水假设</summary><div class="fields"><label>你的相对位置<select :value="scenario.position" @change="emit('update','position',($event.target as HTMLSelectElement).value)"><option value="unknown">未知</option><option value="IP">有位置（后行动）</option><option value="OOP">无位置（先行动）</option></select></label><label>终局底池抽水 %<input inputmode="decimal" :value="scenario.rake" @input="emit('update','rake',($event.target as HTMLInputElement).value)"></label><label>抽水封顶（同金额单位）<input inputmode="decimal" :value="scenario.cap" placeholder="留空表示不封顶" @input="emit('update','cap',($event.target as HTMLInputElement).value)"></label><label v-if="scenario.opponents===1">对手剩余筹码<input inputmode="decimal" :value="scenario.villainStack" @input="emit('update','villainStack',($event.target as HTMLInputElement).value)"></label></div><p v-if="spr()!==null">当前剩余有效筹码 / 当前底池：<strong>{{spr()}}</strong></p><label>下注过程 / 复盘备注<textarea rows="3" :value="scenario.notes" @input="emit('update','notes',($event.target as HTMLTextAreaElement).value)" placeholder="例如 BTN 开牌，BB 跟注；翻牌对手下注半池"></textarea></label><p class="muted">抽水模型：最终底池 × 百分比，与封顶取较小值；未模拟各平台特殊规则。位置仅记录，不会凭它生成伪 GTO 建议。比值仅用于当前筹码深度描述，未扣后续跟注，不是整局策略。多人不合并成单一有效筹码；下注备注不会自动推断范围。</p></details></template>
